    for string_id, key, text in special_upgrade_descriptions:
        key_sym = f"_vf2specialstr_key_{string_id:X}"
        text_sym = f"_vf2specialstr_text_{string_id:X}"
        helper_lines.append(f'const char {key_sym[1:]}[] = "{c_string(key)}";')
