def patch_arcade_behavior_labels(manifest):
    """Give pachinko and pinball their own labels without changing shared text."""
    obj = CoffObject(PATCHED / "Behavior.obj")
    patches = [
        ("?PlayingPachinko@CBehavior@@CAXAAVCVillager@@@Z", behavior_label_string_id_by_key("eString_PlayingPachinko"), "Playing pachinko"),
        ("?PlayingPinball@CBehavior@@CAXAAVCVillager@@@Z", behavior_label_string_id_by_key("eString_PlayingPinball"), "Playing pinball"),
    ]
    changed = []
    for symbol_name, string_id, text in patches:
        symbol = obj.symbol(symbol_name)
        sec = obj.section(symbol.section)
        raw = sec.raw_ptr + symbol.value + 0x51
        expected = b"\x68\x5D\x02\x00\x00"
        if obj.buf[raw:raw + len(expected)] != expected:
            raise ValueError(f"Unexpected shared Playing string in {symbol_name}")
        obj.buf[raw + 1:raw + 5] = struct.pack("<I", string_id)
        changed.append({"behavior": symbol_name, "string_id": hex(string_id), "text": text})
    obj.write(PATCHED / "Behavior.obj")
    manifest["arcade_behavior_labels"] = changed


def restore_supplied_game_table_sprites(manifest):
    """Keep the seeded runtime pool and foosball sheets verbatim."""
    source_root = OUT / "Images" / "Furniture"
    copied = []
    missing = []
    for filename in ("PoolTableStd.png", "FoosballTableStd.png"):
        source = source_root / filename
        target = OUT / "Images" / "Furniture" / filename
        if source.exists():
            copied.append({"file": filename, "bytes": target.stat().st_size, "source": "build-local runtime image"})
        else:
            missing.append(filename)
    manifest["restored_game_table_sprites"] = {"copied": copied, "missing": missing}


def patch_options_dialog(manifest):
    obj = CoffObject(PATCHED / "theOptionsDialog.obj")
    ctor_sym = obj.symbol("??0theOptionsDialog@@QAE@PADW4DialogColorEnum@@@Z")
    sec = obj.section(ctor_sym.section)
    start = sec.raw_ptr + ctor_sym.value

    # Desktop already contains the same Evict button/handler shape as mobile.
    # Force the constructor to create the dormant Evict button in all Settings
    # dialogs, while leaving the native confirmation -> EvictFamily path alone.
    expected_1 = bytes([0x0F, 0x85, 0x80, 0x00, 0x00, 0x00])
    expected_generation_cmp = bytes([0x83, 0x3D, 0x04, 0x00, 0x00, 0x00, 0x02])
    expected_2 = bytes([0x7D, 0x77])
    if obj.buf[start + 0x2DA:start + 0x2E0] != expected_1:
        raise ValueError("Unexpected Evict first skip branch bytes")
    if obj.buf[start + 0x2E0:start + 0x2E7] != expected_generation_cmp:
        raise ValueError("Unexpected Evict generation compare bytes")
    if obj.buf[start + 0x2E7:start + 0x2E9] != expected_2:
        raise ValueError("Unexpected Evict second skip branch bytes")
    obj.buf[start + 0x2DA:start + 0x2E0] = b"\x90" * 6
    obj.buf[start + 0x2E7:start + 0x2E9] = b"\x90" * 2

    add_control_insert = ctor_sym.value + 0x360
    add_control_payload = bytearray([
        0x56,                         # push esi (the Evict ldwButton*)
        0x8B, 0xCB,                   # mov ecx, ebx (this)
        0xE8, 0x00, 0x00, 0x00, 0x00, # call ldwScene::AddControl
    ])
    obj.insert_section_bytes(ctor_sym.section, add_control_insert, add_control_payload)
    add_control_sym = obj.symbol("?AddControl@ldwScene@@IAEXPAVldwControl@@@Z")
    obj.append_relocation(ctor_sym.section, add_control_insert + 4, add_control_sym.index, IMAGE_REL_I386_REL32)
    obj.write(PATCHED / "theOptionsDialog.obj")

    manifest["settings_menu"] = {
        "evict": {
            "status": "button is constructed and added to the Settings control list; native mobile/desktop confirmation and EvictFamily handler are preserved",
            "button_control_id": 4,
            "label_string_id": "0x10",
            "confirmation_string_id": "0x11",
            "handler": "?EvictFamily@theOptionsDialog@@AAEXXZ",
            "family_tree_handler": "?EvictFamily@CFamilyTree@@QAEXXZ",
            "click_safety": "The native mobile/desktop handler path is untouched: confirmation dialog, CFamilyTree::EvictFamily Reset()+evicted mark, villager-manager reset, adoption scene state 2, scene 6.",
            "add_control_patch": {
                "insert_offset": hex(add_control_insert),
                "helper": "?AddControl@ldwScene@@IAEXPAVldwControl@@@Z",
                "note": "The stock dormant block constructs and labels the Evict button but does not add it to the scene; B119 inserts AddControl(this, evictButton).",
            },
            "constructor_patches": [
                {
                    "offset": "0x2DA",
                    "expected_original_bytes": expected_1.hex(),
                    "replacement_bytes": "909090909090",
                    "note": "always allow Evict setup instead of skipping the button on the first stock/mobile state guard",
                },
                {
                    "offset": "0x2E0",
                    "expected_original_bytes": expected_generation_cmp.hex(),
                    "replacement_bytes": expected_generation_cmp.hex(),
                    "note": "generation compare is left intact because the following skip branch is disabled",
                },
                {
                    "offset": "0x2E7",
                    "expected_original_bytes": expected_2.hex(),
                    "replacement_bytes": "9090",
                    "note": "always allow Evict setup instead of skipping the button on the generation gate",
                },
            ],
        }
    }


def patch_added_furniture_click_aliases(manifest):
    """Extend HandleMouseDown's native lookup table for appended furniture."""
    obj = CoffObject(PATCHED / "FurnitureManager.obj")
    sym = obj.symbol("?HandleMouseDown@CFurnitureManager@@QAE_NUldwPoint@@@Z")
    sec = obj.section(sym.section)
    guard_off = sym.value + 0xE3
    raw_guard = sec.raw_ptr + guard_off
    if obj.buf[raw_guard:raw_guard + 5] != b"\x3D\xC0\x00\x00\x00":
        raise ValueError("Unexpected HandleMouseDown lookup bound")
    table_sym = obj.symbol("$LN54")
    if table_sym.section != sym.section or table_sym.value + 0xC1 != sec.raw_size:
        raise ValueError("Unexpected HandleMouseDown native lookup-table layout")

    max_offset = max(item_id_for(idx) - 0x1AD for idx in range(len(ITEMS)))
    old_count = 0xC1
    new_count = max_offset + 1
    obj.insert_section_bytes(sec.index, sec.raw_size, b"\0" * (new_count - old_count))
    sec = obj.section(sym.section)
    table_raw = sec.raw_ptr + table_sym.value
    aliases = []
    aliases = []
    for idx, (_name, donor_id, _list, _path) in enumerate(ITEMS):
        added_id = item_id_for(idx)
        added_offset = added_id - 0x1AD
        donor_offset = donor_id - 0x1AD
        obj.buf[table_raw + added_offset] = obj.buf[table_raw + donor_offset]
        aliases.append({"item": _name, "item_id": hex(added_id), "donor_item": hex(donor_id)})
    struct.pack_into("<I", obj.buf, sec.raw_ptr + guard_off + 1, max_offset)
    obj.write(PATCHED / "FurnitureManager.obj")
    manifest["clickable_added_furniture"] = {
        "status": "native mouse-dispatch table extended with donor case bytes",
        "route": "stock donor lookup case; no detour or generic replacement path",
        "stock_furniture_dispatch": "unmodified",
        "old_lookup_count": old_count,
        "new_lookup_count": new_count,
        "items": aliases,
    }


def validate_vf3_tv_animation_contract(manifest, *, check_files=True):
    """Fail fast if added VF3 TVs drift back to a bad animation orientation."""
    errors = []
    records = {
        row.get("item"): row
        for row in manifest.get("FurnitureManager", {}).get("vf3_tv_animation_records", [])
        if isinstance(row, dict)
    }
    graphic_descs = {
        row.get("label"): row
        for row in manifest.get("theGraphicsManager", {})
        .get("vf3_tv_floating_animation_images", {})
        .get("descriptors", [])
        if isinstance(row, dict)
    }
    floating_entries = {
        row.get("label"): row
        for row in manifest.get("FloatingAnim", {}).get("private_vf3_tv_entries", [])
        if isinstance(row, dict)
    }

    for item in VF3_TV_ITEMS:
        frame0_label, frame1_label = item["animation_labels"]
        row = records.get(item["short_description"])
        if row is None:
            errors.append(f"missing VF3 TV animation record for {item['short_description']}")
            continue
        expected = {
            "item_id": hex(item["item_id"]),
            "frame0_label": frame0_label,
            "frame1_label": frame1_label,
            "frame0_enum": hex(VF3_TV_FLOATING_ANIMS[frame0_label]["enum"]),
            "frame1_enum": hex(VF3_TV_FLOATING_ANIMS[frame1_label]["enum"]),
        }
        for key, value in expected.items():
            if row.get(key) != value:
                errors.append(f"{item['short_description']} {key} expected {value}, got {row.get(key)}")

    for label, info in VF3_TV_FLOATING_ANIMS.items():
        expected_enum = hex(info["enum"])
        expected_runtime = VF3_TV_RUNTIME_ANIMATION_NAMES[label]
        graphic = graphic_descs.get(label)
        floating = floating_entries.get(label)
        if graphic is None:
            errors.append(f"missing graphics descriptor for VF3 TV animation {label}")
        else:
            if graphic.get("floating_anim_enum") != expected_enum:
                errors.append(
                    f"{label} graphics descriptor enum expected {expected_enum}, got {graphic.get('floating_anim_enum')}"
                )
            if graphic.get("path") != expected_runtime:
                errors.append(f"{label} graphics descriptor path expected {expected_runtime}, got {graphic.get('path')}")
            if graphic.get("grid") != [6, 3]:
                errors.append(f"{label} graphics descriptor grid expected [6, 3], got {graphic.get('grid')}")
        if floating is None:
            errors.append(f"missing floating-animation table entry for VF3 TV animation {label}")
        else:
            if floating.get("enum") != expected_enum:
                errors.append(f"{label} floating-animation enum expected {expected_enum}, got {floating.get('enum')}")
            if floating.get("runtime_name") != expected_runtime:
                errors.append(
                    f"{label} floating-animation runtime expected {expected_runtime}, got {floating.get('runtime_name')}"
                )
            if floating.get("frames") != 18:
                errors.append(f"{label} floating-animation frame count expected 18, got {floating.get('frames')}")
        if check_files:
            runtime_path = OUT / "Images" / expected_runtime
            if not runtime_path.is_file():
                errors.append(f"missing generated VF3 TV runtime animation asset: {runtime_path}")
            else:
                try:
                    from PIL import Image

                    with Image.open(runtime_path).convert("RGBA") as runtime_image:
                        if runtime_image.width % 6 != 0 or runtime_image.height % 3 != 0:
                            errors.append(
                                f"{label} runtime animation sheet is not divisible by 6x3: {runtime_image.size}"
                            )
                        if not runtime_image.getchannel("A").getbbox():
                            errors.append(f"{label} runtime animation sheet is fully transparent: {runtime_path}")
                except Exception as exc:
                    errors.append(f"{label} runtime animation sheet could not be audited: {runtime_path}: {exc}")

    missing_assets = manifest.get("vf3_tv_animation_sheets", {}).get("missing", [])
    runtime_assets_available = all(
        (OUT / "Images" / runtime_name).is_file()
        for runtime_name in VF3_TV_RUNTIME_ANIMATION_NAMES.values()
    )
    if missing_assets and not runtime_assets_available:
        errors.append(f"missing VF3 TV animation source/output assets: {missing_assets}")
    if errors:
        raise RuntimeError("VF3 TV animation contract failed:\n- " + "\n- ".join(errors))

    manifest["vf3_tv_animation_contract"] = {
        "status": "validated",
        "frame_order": "generated furniture frame 0 uses the non-East private strip; frame 1 uses the East private strip",
        "items": [
            {
                "item": item["short_description"],
                "item_id": hex(item["item_id"]),
                "frame0_label": item["animation_labels"][0],
                "frame1_label": item["animation_labels"][1],
            }
            for item in VF3_TV_ITEMS
        ],
        "runtime_assets": list(VF3_TV_RUNTIME_ANIMATION_NAMES.values()),
        "source_frame_status": "external source frames missing; validated from build-local runtime animation strips"
        if missing_assets
        else "source and runtime animation assets validated",
    }


def validate_vf3_tv_behavior_contract(manifest):
    """Fail fast if added VF3 TVs cannot be discovered by stock TV behavior."""
    errors = []
    furniture = manifest.get("FurnitureManager", {})
    load_fmap_patch = furniture.get("load_fmap_range_patch", {})
    if load_fmap_patch.get("new_max_offset") != furniture.get("new_item_max_offset"):
        errors.append(
            "CFurnitureManager::LoadFmap max offset does not match the expanded furniture max offset"
        )
    behavior_rows = {
        row.get("item"): row
        for row in furniture.get("vf3_tv_behavior_contracts", [])
        if isinstance(row, dict)
    }
    fmap_rows = {
        row.get("item"): row
        for row in manifest.get("vf3_tv_fmaps", {}).get("generated", [])
        if isinstance(row, dict)
    }
    fmap_issues = manifest.get("vf3_tv_fmaps", {}).get("issues", [])
    if fmap_issues:
        errors.append(f"VF3 TV fmap generation issues: {fmap_issues}")
    for item in VF3_TV_ITEMS:
        name = item["short_description"]
        behavior = behavior_rows.get(name)
        if behavior is None:
            errors.append(f"missing VF3 TV behavior contract for {name}")
        else:
            if behavior.get("item_id") != hex(item["item_id"]):
                errors.append(f"{name} behavior contract item id expected {hex(item['item_id'])}, got {behavior.get('item_id')}")
            if behavior.get("donor_item") != hex(item["donor"]):
                errors.append(f"{name} behavior contract donor expected {hex(item['donor'])}, got {behavior.get('donor_item')}")
            if behavior.get("item_type") != 5:
                errors.append(f"{name} item_type expected base TV type 5, got {behavior.get('item_type')}")
        fmap = fmap_rows.get(name)
        if fmap is None:
            errors.append(f"missing generated TV fmap for {name}")
        elif not fmap.get("cell_values"):
            errors.append(f"{name} generated TV fmap has no nonzero object cells")
    if errors:
        raise RuntimeError("VF3 TV behavior contract failed:\n- " + "\n- ".join(errors))
    manifest["vf3_tv_behavior_contract"] = {
        "status": "validated",
        "recognition_path": "CBehavior::WatchTVDispatch -> CFurnitureManager::FindFurniture(object 0x0D) -> FurnitureHasObject",
        "load_fmap_patch": load_fmap_patch,
        "items": [
            {
                "item": item["short_description"],
                "item_id": hex(item["item_id"]),
                "donor_item": hex(item["donor"]),
                "fmap": f"{item['name']}.png.fmap",
            }
            for item in VF3_TV_ITEMS
        ],
    }


def validate_invisible_hammock_behavior_contract(manifest):
    """Fail fast if Invisible Hammock stops inheriting the stock hammock path."""
    errors = []
    furniture = manifest.get("FurnitureManager", {})
    rows = {
        row.get("item_id"): row
        for row in furniture.get("invisible_hammock_behavior_contracts", [])
        if isinstance(row, dict)
    }
    row = rows.get("0x30c")
    if row is None:
        errors.append("missing Invisible Hammock furniture behavior contract")
    else:
        if row.get("donor_item") != "0x1e1":
            errors.append(f"Invisible Hammock donor expected 0x1e1, got {row.get('donor_item')}")
        if row.get("item_type") != 5:
            errors.append(f"Invisible Hammock item_type expected 5, got {row.get('item_type')}")

    click_aliases = {
        row.get("item_id"): row
        for row in manifest.get("clickable_added_furniture", {}).get("items", [])
        if isinstance(row, dict)
    }
    alias = click_aliases.get("0x30c")
    if alias is None:
        errors.append("missing Invisible Hammock donor click alias")
    elif alias.get("donor_item") != "0x1e1":
        errors.append(f"Invisible Hammock click alias donor expected 0x1e1, got {alias.get('donor_item')}")

    drop = manifest.get("invisible_hammock_drop_action", {})
    if drop.get("base_item") != "0x1E1" or drop.get("added_item") != "0x30C":
        errors.append("Invisible Hammock drop gate must accept base 0x1E1 and added 0x30C")
    if drop.get("native_behavior") != "eBehavior_LieInHammockNoLeadIn (0x24)":
        errors.append(f"Invisible Hammock native behavior drifted: {drop.get('native_behavior')}")
    if drop.get("hotspot_modified") is not True:
        errors.append("Invisible Hammock must widen stock CHotSpot::Hammock drop gate")
    if drop.get("matches_base_hammock_behavior") is not True:
        errors.append("Invisible Hammock must continue through the base hammock behavior route")

    behavior_assets = manifest.get("behavior_assets", {})
    fmap_rows = {
        row.get("target"): row
        for row in behavior_assets.get("invisible_outdoor_fmap_donors", [])
        if isinstance(row, dict)
    }
    fmap = fmap_rows.get("InvisibleHammock.png.fmap")
    if fmap is None:
        errors.append("missing InvisibleHammock.png.fmap donor copy")
    elif fmap.get("donor") != "HammockStd.png.fmap":
        errors.append(f"Invisible Hammock fmap donor expected HammockStd.png.fmap, got {fmap.get('donor')}")
    for missing in behavior_assets.get("missing", []):
        if isinstance(missing, dict) and missing.get("target") == "InvisibleHammock.png.fmap":
            errors.append(f"Invisible Hammock fmap was reported missing: {missing}")

    if errors:
        raise RuntimeError("Invisible Hammock behavior contract failed:\n- " + "\n- ".join(errors))
    manifest["invisible_hammock_behavior_contract"] = {
        "status": "validated",
        "item_id": "0x30c",
        "donor_item": "0x1e1",
        "record_contract": row,
        "click_alias": alias,
        "hotspot": drop,
        "fmap": fmap,
        "recognition_path": "InvisibleHammock inherits the donor itemInfo/click/fmap path and widens CHotSpot::Hammock's initial in-world gate so the stock base hammock drop behavior runs.",
    }


