def validate_native_north_bathroom_malfunction_selection(manifest):
    obj = CoffObject(PATCHED / "theMainScene.obj")
    update = obj.symbol("?UpdateScene@theMainScene@@MAEXXZ")
    section = obj.section(update.section)
    data = bytes(obj.buf[section.raw_ptr + update.value : section.raw_ptr + section.raw_size])
    cases = [
        {
            "name": "north shower leak",
            "case_offset": 0x459,
            "permanent_fix_offset": 0x11C,
            "upgrade_check_offset": 0x469,
            "prop_offset": 0x480,
            "prop": 0x49,
        },
        {
            "name": "north toilet leak",
            "case_offset": 0x487,
            "permanent_fix_offset": 0x10C,
            "upgrade_check_offset": 0x497,
            "prop_offset": 0x4AA,
            "prop": 0x48,
        },
        {
            "name": "north sink leak",
            "case_offset": 0x4AE,
            "permanent_fix_offset": 0x12C,
            "upgrade_check_offset": 0x4BA,
            "prop_offset": 0x4CD,
            "prop": 0x4A,
        },
    ]
    for row in cases:
        case_off = row["case_offset"]
        state_pattern = b"\x8B\x43\x14\x80\xB8" + struct.pack(
            "<I",
            row["permanent_fix_offset"],
        ) + b"\x00"
        if data[case_off : case_off + len(state_pattern)] != state_pattern:
            raise RuntimeError(f"Native {row['name']} permanent-fix gate drifted")
        upgrade_off = row["upgrade_check_offset"]
        if data[upgrade_off : upgrade_off + 5] != b"\x68\xE6\x00\x00\x00":
            raise RuntimeError(f"Native {row['name']} renovation gate drifted")
        prop_off = row["prop_offset"]
        if data[prop_off : prop_off + 2] != b"\x6A" + bytes([row["prop"]]):
            raise RuntimeError(f"Native {row['name']} SetProp selection drifted")

    manifest["native_north_bathroom_malfunctions"] = {
        "status": "validated and preserved",
        "function": "?UpdateScene@theMainScene@@MAEXXZ",
        "selection": "stock standalone random-malfunction jump-table cases",
        "second_bathroom_upgrade": "0xE6",
        "cases": [
            {
                "name": row["name"],
                "prop": hex(row["prop"]),
                "permanent_fix_world_state_byte": hex(row["permanent_fix_offset"]),
            }
            for row in cases
        ],
    }


def validate_native_dryer_lint_fire_contract(manifest):
    """Keep the stock Dryer-gated lint fire and its Handyman repair path intact."""

    def relocation_target(obj, section, vaddr):
        for index in range(section.nreloc):
            reloc_off = section.reloc_ptr + index * 10
            reloc_vaddr, symbol_index, _rtype = struct.unpack_from("<IIH", obj.buf, reloc_off)
            if reloc_vaddr == vaddr:
                return obj.symbol_by_index[symbol_index]
        raise RuntimeError(f"Missing relocation at section offset {vaddr:#x}")

    main_obj = CoffObject(PATCHED / "theMainScene.obj")
    update = main_obj.symbol("?UpdateScene@theMainScene@@MAEXXZ")
    update_sec = main_obj.section(update.section)
    update_data = bytes(
        main_obj.buf[
            update_sec.raw_ptr + update.value :
            update_sec.raw_ptr + update_sec.raw_size
        ]
    )
    if update_data[0x41D : 0x427] != b"\x8B\x43\x14\x80\xB8\xCC\x00\x00\x00\x00":
        raise RuntimeError("Native Dryer lint-fire permanent-fix gate drifted")
    if update_data[0x443 : 0x445] != b"\x6A\x48":
        raise RuntimeError("Native Dryer lint-fire furniture gate drifted")
    if update_data[0x452 : 0x454] != b"\x6A\x21":
        raise RuntimeError("Native Dryer lint-fire SetProp selection drifted")
    find_target = relocation_target(main_obj, update_sec, update.value + 0x446)
    if find_target.name != "?FindFurniture@CFurnitureManager@@QAE_NW4EObject@CContentMap@@UldwPoint@@AAUsFurnitureInfo2@@_NH3@Z":
        raise RuntimeError("Native Dryer lint-fire furniture lookup no longer calls FindFurniture")
    dryer_case = relocation_target(main_obj, update_sec, update.value + 0x1094)
    if dryer_case.section != update.section or dryer_case.value != update.value + 0x41D:
        raise RuntimeError("Native random-malfunction jump table no longer reaches the Dryer case")

    behavior_obj = CoffObject(PATCHED / "Behavior.obj")
    fixing = behavior_obj.symbol("?FixingLaundryFire@CBehavior@@CAXAAVCVillager@@@Z")
    fixing_sec = behavior_obj.section(fixing.section)
    fixing_data = bytes(
        behavior_obj.buf[
            fixing_sec.raw_ptr + fixing.value :
            fixing_sec.raw_ptr + fixing_sec.raw_size
        ]
    )
    if fixing_data[0x10B : 0x111] != b"\x6A\x21\x8B\xCE\xE8\x00":
        raise RuntimeError("Native Dryer lint-fire repair no longer deactivates prop 0x21")
    if fixing_data[0x114 : 0x11B] != b"\x6A\x00\x6A\x3A\x8B\xCE\xE8":
        raise RuntimeError("Native Dryer lint-fire repair no longer advances Handyman 0x3A")

    manifest["native_dryer_lint_fire"] = {
        "status": "validated and preserved",
        "selection": "stock random-malfunction jump-table case",
        "dryer_object": "0x48",
        "malfunction_prop": "0x21",
        "permanent_fix_world_state_byte": "0xcc",
        "requires_dryer_in_house": True,
        "repair_behavior": "CBehavior::FixingLaundryFire",
        "repair_clears_prop": "0x21",
        "repair_advances_achievement": "0x3a",
        "achievement_name": "Handyman",
    }


def validate_runtime_payload_contract(manifest):
    errors = []
    for filename in VANILLA_RUNTIME_REQUIRED_FILES:
        if not (OUT / filename).is_file():
            errors.append(f"missing required runtime file: {filename}")
    for dirname in OFFICIAL_B93_RELEASE_REQUIRED_DIRS:
        if not (OUT / dirname).is_dir():
            errors.append(f"missing required runtime directory: {dirname}")

    images_dir = OUT / "Images"
    sounds_dir = OUT / "Sounds"
    image_count = count_files(images_dir)
    sound_count = count_files(sounds_dir)
    if image_count < RUNTIME_MIN_IMAGE_FILE_COUNT:
        errors.append(f"Images payload is incomplete: {image_count} files, expected at least {RUNTIME_MIN_IMAGE_FILE_COUNT}")
    if sound_count < RUNTIME_MIN_SOUND_FILE_COUNT:
        errors.append(f"Sounds payload is incomplete: {sound_count} files, expected at least {RUNTIME_MIN_SOUND_FILE_COUNT}")

    for filename in RUNTIME_REQUIRED_IMAGE_FILES:
        if not (images_dir / filename).is_file():
            errors.append(f"missing required base image: Images/{filename}")
    for filename in DESKTOP_RUNTIME_DLL_NAMES:
        if not (OUT / filename).is_file():
            errors.append(f"missing required desktop runtime DLL: {filename}")

    for dirname in REMOVED_LEGACY_PACKAGE_DIRS:
        if (OUT / dirname).exists():
            errors.append(f"legacy package directory should not be present in official B93-shaped builds: {dirname}")

    if errors:
        raise RuntimeError("Runtime payload contract failed:\n- " + "\n- ".join(errors))

    manifest["runtime_payload_contract"] = {
        "status": "validated",
        "images_file_count": image_count,
        "sounds_file_count": sound_count,
        "required_root_files": list(VANILLA_RUNTIME_REQUIRED_FILES),
        "required_root_dirs": list(OFFICIAL_B93_RELEASE_REQUIRED_DIRS),
        "required_images": list(RUNTIME_REQUIRED_IMAGE_FILES),
        "required_dlls": list(DESKTOP_RUNTIME_DLL_NAMES),
        "official_b93_release_asset": OFFICIAL_B93_RELEASE_ASSET,
        "official_b93_release_sha256": OFFICIAL_B93_RELEASE_SHA256,
        "removed_legacy_dirs": list(REMOVED_LEGACY_PACKAGE_DIRS),
        "release_note": "The standalone B98-current ZIP is the package baseline. Future release folders must preserve its runtime/support folder shape, use a short VF2-B##-Release name, and replace only the packaged EXE with the newest build EXE.",
    }


def validate_custom_achievement_award_hook_objects(manifest):
    errors = []

    def function_data(obj, name):
        sym = obj.symbol(name)
        sec = obj.section(sym.section)
        return bytes(
            obj.buf[sec.raw_ptr + sym.value : sec.raw_ptr + sec.raw_size]
        ), sym, sec

    def relocation_targets(obj, sym, sec):
        return {
            vaddr - sym.value: (obj.symbol_by_index[symbol_index].name, rtype)
            for vaddr, symbol_index, rtype in (
                struct.unpack_from("<IIH", obj.buf, sec.reloc_ptr + index * 10)
                for index in range(sec.nreloc)
            )
            if sym.value <= vaddr < sec.raw_size
        }

    store_obj = CoffObject(PATCHED / "ScrollingStoreScene.obj")
    purchase_data, purchase_sym, purchase_sec = function_data(
        store_obj, "?HandlePurchaseItem@CScrollingStoreScene@@AAEXXZ"
    )
    expected_purchase_window = (
        b"\x3D\x28\x03\x00\x00\x7D\x39\x50"
        b"\xB9\x00\x00\x00\x00\xE8\x00\x00\x00\x00"
        b"\xE8\x00\x00\x00\x00\x8B\xC8\xE8\x00\x00\x00\x00"
    )
    if purchase_data[0x2D0:0x2EE] != expected_purchase_window:
        errors.append("HandlePurchaseItem purchase-award call window drifted")
    if purchase_data[0x360:0x36C] != b"\xE8\x00\x00\x00\x00\x8B\xC8\xE8\x00\x00\x00\x00":
        errors.append("HandlePurchaseItem stock save call window drifted")
    purchase_targets = relocation_targets(store_obj, purchase_sym, purchase_sec)
    expected_purchase_targets = {
        0x2D9: ("?FurnitureManager@@3VCFurnitureManager@@A", 0x0006),
        0x2DE: (
            "?AddToStorageAndAward@CFurnitureManager@@QAE_NW4EInventoryItem@@@Z",
            IMAGE_REL_I386_REL32,
        ),
        0x2E3: ("?Get@theMainScene@@SAPAV1@XZ", IMAGE_REL_I386_REL32),
        0x2EA: ("?TurnDecorateModeOn@theMainScene@@QAEXXZ", IMAGE_REL_I386_REL32),
        0x361: ("?Get@theGameState@@SAPAV1@XZ", IMAGE_REL_I386_REL32),
        0x368: ("?SaveCurrentGame@theGameState@@QAE_NXZ", IMAGE_REL_I386_REL32),
    }
    for offset, expected in expected_purchase_targets.items():
        if purchase_targets.get(offset) != expected:
            errors.append(
                f"HandlePurchaseItem relocation {offset:#x} expected {expected}, "
                f"got {purchase_targets.get(offset)}"
            )

    special_helper = PATCHED / "vf2_special_upgrade_effects.cpp"
    helper_text = special_helper.read_text(encoding="ascii") if special_helper.is_file() else ""
    if helper_text.count("enum EInventoryItem") != 1:
        errors.append("special helper must define EInventoryItem exactly once")
    if helper_text.count("class CFurnitureManager") != 1:
        errors.append("special helper must define CFurnitureManager exactly once")
    wrapper_marker = "bool CFurnitureManager::AddToStorageAndAward(EInventoryItem item)"
    if wrapper_marker not in helper_text:
        errors.append("special helper is missing the same-thiscall purchase wrapper")
    else:
        wrapper = helper_text.split(wrapper_marker, 1)[1].split("struct sFurnitureInfo", 1)[0]
        required_order = (
            "bool stored = AddToStorage(item);",
            "if (stored)",
            "VF2DispatchSuccessfulFurniturePurchase(item);",
            "return stored;",
        )
        try:
            positions = [wrapper.index(token) for token in required_order]
            if positions != sorted(positions):
                errors.append("purchase wrapper does not call native first and return its exact bool")
        except ValueError:
            errors.append("purchase wrapper source contract is incomplete")

    behavior_contract = {
        "enabled": ENABLE_BEHAVIOR_PATCHES,
        "praise_hook": None,
        "scold_hook": None,
    }
    if ENABLE_BEHAVIOR_PATCHES:
        main_obj = CoffObject(PATCHED / "theMainScene.obj")
        stock_main = CoffObject(SRC_OBJS / "theMainScene.obj")
        for function_name, replacements in (
            (
                "?InvokeReward@theMainScene@@IAEXAAVCVillager@@@Z",
                {
                    0x36B: "_VF2PraiseCaptureAndForget@8",
                    0x3B7: "_VF2PraiseStartAndRestore@4",
                },
            ),
            (
                "?InvokeScolding@theMainScene@@IAEXAAVCVillager@@@Z",
                {0x118: "_VF2ScoldAwardAndForget@8"},
            ),
        ):
            patched_data, patched_sym, patched_sec = function_data(main_obj, function_name)
            stock_data, stock_sym, stock_sec = function_data(stock_main, function_name)
            if patched_data != stock_data:
                errors.append(f"{function_name} instruction bytes changed instead of relocation-only hooks")
            patched_targets = relocation_targets(main_obj, patched_sym, patched_sec)
            stock_targets = relocation_targets(stock_main, stock_sym, stock_sec)
            for offset, stock_target in stock_targets.items():
                expected_name = replacements.get(offset, stock_target[0])
                expected = (expected_name, stock_target[1])
                if patched_targets.get(offset) != expected:
                    errors.append(
                        f"{function_name} relocation {offset:#x} expected {expected}, "
                        f"got {patched_targets.get(offset)}"
                    )
        behavior_helper = PATCHED / "vf2_spontaneous_behaviors.cpp"
        behavior_text = behavior_helper.read_text(encoding="ascii") if behavior_helper.is_file() else ""
        for label, goal_id in CUSTOM_ACHIEVEMENT_PRAISE_LABEL_GOALS.items():
            if (
                f'VF2RawBehaviorLabelEquals(label, "{label}")' not in behavior_text
                or f"Achievement.SetComplete((EAchievement)0x{goal_id:X})" not in behavior_text
            ):
                errors.append(f"behavior helper missing exact praise award {label!r}")
        scold_marker = 'extern "C" void __stdcall VF2ScoldAwardAndForget'
        if scold_marker not in behavior_text:
            errors.append("behavior helper missing scold wrapper")
        else:
            scold_source = behavior_text.split(scold_marker, 1)[1].split("class CFurnitureManager", 1)[0]
            if scold_source.count("plans->ForgetPlans") != 1:
                errors.append("scold wrapper must call native ForgetPlans exactly once")
            if "VF2RestoreRawPraiseLabel" in scold_source:
                errors.append("scold wrapper must not restore the old label")
        behavior_contract = {
            "enabled": True,
            "praise_hook": "InvokeReward+0x36B",
            "praise_restore_hook": "InvokeReward+0x3B7",
            "scold_hook": "InvokeScolding+0x118",
            "relocation_only": True,
            "over_praise_paths_unchanged": True,
        }

    if errors:
        raise RuntimeError(
            "Custom achievement award-hook object contract failed:\n- "
            + "\n- ".join(errors)
        )
    manifest["custom_achievement_award_hook_contract"] = {
        "status": "validated",
        "purchase": {
            "hook": "HandlePurchaseItem+0x2DE",
            "wrapper": "CFurnitureManager::AddToStorageAndAward",
            "same_thiscall_abi": True,
            "native_result_preserved": True,
            "stock_save_relocation": "0x368",
        },
        "behavior": behavior_contract,
    }


def patch_maximum_resource_achievement_callsites(manifest):
    """Route native resource mutations through ABI-compatible goal observers."""
    wrappers = {
        "?Adjust@CMoney@@QAEXM_N@Z": "@VF2MoneyAdjustAndAward@16",
        "?Set@CMoney@@QAEXN@Z": "@VF2MoneySetAndAward@16",
        "?Adjust@CFoodStore@@QAEXH@Z": "@VF2FoodAdjustAndAward@12",
        "?LoadState@CMoney@@QAE?B_NABUSSaveState@1@@Z": (
            "@VF2MoneyLoadStateAndReconcile@12"
        ),
    }
    patched = {native: [] for native in wrappers}

    for path in sorted(PATCHED.glob("*.obj")):
        obj = CoffObject(path)
        matches = []
        for section in obj.sections:
            for index in range(section.nreloc):
                vaddr, symbol_index, relocation_type = struct.unpack_from(
                    "<IIH", obj.buf, section.reloc_ptr + index * 10
                )
                symbol = obj.symbol_by_index.get(symbol_index)
                if (
                    symbol is not None
                    and symbol.name in wrappers
                    and relocation_type == IMAGE_REL_I386_REL32
                ):
                    matches.append(
                        (section.index, vaddr, symbol.name, relocation_type)
                    )
        if not matches:
            continue

        wrapper_symbols = {
            native: obj.append_undefined_symbol(wrappers[native])
            for _section, _vaddr, native, _relocation_type in matches
        }
        for section, vaddr, native, relocation_type in matches:
            obj.retarget_relocation(
                section,
                vaddr,
                wrapper_symbols[native],
                relocation_type,
            )
            patched[native].append(
                {
                    "object": path.name,
                    "section": section,
                    "offset": hex(vaddr),
                    "wrapper": wrappers[native],
                }
            )
        obj.write(path)

    missing = [native for native, callsites in patched.items() if not callsites]
    if missing:
        raise RuntimeError(
            "Maximum-resource achievement observers found no native calls for: "
            + ", ".join(missing)
        )
    if len(patched["?LoadState@CMoney@@QAE?B_NABUSSaveState@1@@Z"]) != 1:
        raise RuntimeError(
            "Expected exactly one CMoney::LoadState reconciliation callsite"
        )

    manifest["maximum_resource_achievement_hooks"] = {
        "status": "patched",
        "money_goal": {
            "achievement_id": "0x83",
            "threshold": "4000000000.0",
        },
        "food_goal": {
            "achievement_id": "0x84",
            "threshold": "0x7fffffff",
        },
        "callsites": patched,
        "load_reconciliation": "CMoney::LoadState after FoodStore and achievements",
        "reset_semantics": (
            "event-driven; reset remains cleared until a resource mutation "
            "or successful load-state reconciliation"
        ),
    }


